<template><form class="sf-message-composer" :aria-busy="disabled?'true':'false'" @submit.prevent="submit" @keydown="keydown"><sf-field ref="field" class="sf-message-composer__field" :value="value" :label="label" :placeholder="placeholder" :disabled="disabled" :maxlength="maxlength" multiline :rows="1" @input="$emit('input',$event)"/><button ref="send" class="sf-message-composer__send" type="submit" data-action="send" :disabled="disabled||sendDisabled||!value.trim()" :aria-describedby="sendDisabled?'coach-allowance-status':null" aria-label="Send message"><img :src="sendIcon" alt="" data-source-asset="true"></button></form></template>
<script>
import SfField from './SfField'
export default {name:'SfMessageComposer',components:{SfField},props:{value:{type:String,default:''},disabled:Boolean,sendDisabled:Boolean,label:{type:String,default:'Message AI'},placeholder:{type:String,default:'Message AI...'},maxlength:{type:Number,default:5000},sendIcon:{type:String,default:'/assets/figma/restored/source_chat/imgGroup257.svg'}},watch:{value(){this.resize()}},mounted(){this.resize()},methods:{submit(){if(!this.disabled&&!this.sendDisabled&&this.value.trim())this.$emit('send')},keydown(event){if(event.key!=='Enter'||event.target.tagName!=='TEXTAREA'||event.shiftKey||event.isComposing||event.keyCode===229)return;event.preventDefault();event.stopPropagation();this.submit()},resize(){this.$nextTick(()=>{const field=this.$refs.field.$el.querySelector('textarea');field.style.height='auto';field.style.height=Math.min(112,Math.max(32,field.scrollHeight))+'px';this.$emit('resize',Math.ceil(this.$el.getBoundingClientRect().height))})},focus(){this.$refs.field.$el.querySelector('textarea').focus()}}}
</script>
